function render(state={},data={}){const s={screen:'camp',selected:null,modal:null,stageId:'ST01',...state},d=data.product||data;let fn=pages[s.screen]||camp,overlay=['choice','gearReward','awakening','pause','down','result'].includes(s.screen),cls=s.screen==='camp'?'camp-screen':s.screen==='battle'?'battle-screen':overlay?'overlay-screen':'sheet-screen';return `<div class="ds-screen ${cls}" style="--ds-camp-image:url('${asset('sources/camp-ground-only.png')}');--ds-map-image:url('${mapSource}');--ref-panel-image:url('${uiAsset('card')}');--round-art:url('${uiAsset('round')}')" data-screen="${E(s.screen)}" data-reduced="${!!s.reduced}">${s.modal?'<div class="ds-underlay" inert aria-hidden="true">'+fn(s,d)+'</div>':fn(s,d)}${modal(s,d)}</div>`;}
window.DesignScreens={readyScreens:Object.keys(pages),coreGate:'root-internal-core-gate-passed-only-not-user-approval',version:'final-design-ui.20261106-review.2',render,screens:Object.keys(pages),modals:['confirmDepart','upgradeConfirm','resourceShort','locked','detail','loadError','saveError','saveConflict','fullSlots','maxLevel','adCancelled','adError','restartConfirm'],art:{base:artBase,keys:UI},assets:{camp:asset('sources/camp-ground-only.png'),hero,downHero,map:mapSource,font:fontSource,skillIcons:new URL('visuals/skill-icon-atlas.png',sharedBase).href,sharedBase}};
